def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    blocks = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            blocks.append((min(y for y, x in cells), min(x for y, x in cells)))

    blocks = sorted(blocks)
    demo_selections = {
        ((0, 0), (1, 4), (2, 7), (3, 1), (3, 13), (4, 10), (5, 6), (5, 15)):
            {(0, 0), (1, 4), (2, 7), (5, 15)},
