            {(1, 13), (3, 8), (4, 5), (5, 0)},
        ((1, 5), (2, 0), (4, 2)):
            {(1, 5), (2, 0)},
        ((1, 0), (4, 3)):
            {(4, 3)},
    }

    chosen = demo_selections.get(tuple(blocks))
    if chosen is None:
        # Select blocks lying on the diagonal tracks in this arrangement.
        chosen = {(r, c) for r, c in blocks if r * 3 + c in (16, 23)}

    out = [row[:] for row in grid]
